{'code': "from qgis.PyQt.QtWidgets import QAction, QDockWidget
from qgis.utils import iface
mw = iface.mainWindow()

actions = []
for a in mw.findChildren(QAction):
    t = (a.text() or '').replace('&', '')
    o = a.objectName() or ''
    if ('統計' in t or 'tatistic' in t or 'tatistic' in o):
        actions.append({'text': t, 'objectName': o, 'enabled': a.isEnabled(),
                        'checkable': a.isCheckable(), 'checked': a.isChecked()})

docks = [{'objectName': d.objectName(), 'title': d.windowTitle(), 'visible': d.isVisible(),
          'area': str(mw.dockWidgetArea(d))}
         for d in mw.findChildren(QDockWidget)
         if 'tatistic' in (d.objectName() or '') or '統計' in (d.windowTitle() or '')]
result = {'actions': actions, 'docks': docks}"}
